function isPlateActive(o:LevelObject){return isPlatePressed(o,objects);}
function randFactory(seed:number){let s=seed>>>0;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296;};}
function drawEditorGrid(){clearGroup(editorGrid);const panel=document.querySelector('#editorPanel');if(!panel||panel.classList.contains('hidden'))return;const targetH=Number(document.querySelector<HTMLInputElement>('#editorElevation')?.value??0)||0;const coords=new Map<string,{q:number;r:number;h:number}>();for(const c of level.board.cells){for(let dq=-1;dq<=1;dq++)for(let dr=-1;dr<=1;dr++){if(Math.abs(dq+dr)>1)continue;const q=c.q+dq,r=c.r+dr;coords.set(`${q},${r},${targetH}`,{q,r,h:targetH});}}const material=new THREE.LineBasicMaterial({color:'#d7ffe9',transparent:true,opacity:.62,depthTest:false});for(const hex of coords.values()){const center=hexWorld(hex);const points:THREE.Vector3[]=[];for(let i=0;i<6;i++){const a=Math.PI/3*i+Math.PI/6;points.push(new THREE.Vector3(center.x+Math.cos(a)*1.02,center.y+.035,center.z+Math.sin(a)*1.02));}points.push(points[0].clone());const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),material);line.renderOrder=10;line.userData.editorHex=hex;editorGrid.add(line);const hit=new THREE.Mesh(new THREE.CylinderGeometry(.96,.96,.025,6),new THREE.MeshBasicMaterial({transparent:true,opacity:0.001,depthWrite:false,side:THREE.DoubleSide}));hit.position.set(center.x,center.y+.015,center.z);hit.userData.editorHex=hex;hit.userData.cell=hex;editorGrid.add(hit);}}
function drawHoverConnections(id:string|null){const editorVisible=!document.querySelector('#editorPanel')?.classList.contains('hidden');drawAllConnections(editorVisible?null:id);}
function drawAllConnections(hoveredId:string|null=null){clearGroup(connectionLines);const editorVisible=!document.querySelector('#editorPanel')?.classList.contains('hidden');const edges:{from:LevelObject;to:LevelObject;color:string}[]=[];for(const target of objects){if(target.linkedTo){const source=objects.find(o=>o.id===target.linkedTo);if(source){edges.push({from:source,to:target,color:'#9d8cff'});if(['lift','teleporter'].includes(source.type)&&source.type===target.type)edges.push({from:target,to:source,color:'#9d8cff'});}}for(const sourceId of target.linkedToAll??[]){const source=objects.find(o=>o.id===sourceId);if(source)edges.push({from:source,to:target,color:'#ffc66d'});}if(target.enabledBy){const source=objects.find(o=>o.id===target.enabledBy);if(source)edges.push({from:source,to:target,color:'#56e0d0'});}}const seen=new Set<string>();for(const edge of edges){if(!editorVisible&&(!hoveredId||![edge.from.id,edge.to.id].includes(hoveredId)))continue;const edgeKey=`${edge.from.id}>${edge.to.id}`;if(seen.has(edgeKey))continue;seen.add(edgeKey);const a=hexWorld(edge.from).add(new THREE.Vector3(0,.27,0));const b=hexWorld(edge.to).add(new THREE.Vector3(0,.27,0));const tube=new THREE.Mesh(new THREE.TubeGeometry(new THREE.LineCurve3(a,b),24,.055,8,false),new THREE.MeshBasicMaterial({color:edge.color,transparent:true,opacity:.92,depthTest:false,depthWrite:false,toneMapped:false}));tube.renderOrder=999;connectionLines.add(tube);const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints([a,b]),new THREE.LineDashedMaterial({color:edge.color,dashSize:.42,gapSize:.08,linewidth:4,transparent:true,opacity:1,depthTest:false,depthWrite:false,toneMapped:false}));line.computeLineDistances();line.renderOrder=1000;line.userData.flowMaterial=line.material;connectionLines.add(line);const direction=b.clone().sub(a).normalize();const arrow=new THREE.Mesh(new THREE.ConeGeometry(.095,.27,6),new THREE.MeshBasicMaterial({color:edge.color,transparent:true,opacity:1,depthTest:false,depthWrite:false,toneMapped:false}));arrow.position.copy(b.clone().lerp(a,.16));arrow.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),direction);arrow.renderOrder=1001;connectionLines.add(arrow);}}


