function updateHud(){document.querySelector('#levelName')!.textContent=level.metadata.name;document.querySelector('#moveCount')!.textContent=String(moves);document.querySelector('#moveLimit')!.textContent=level.rules.moveLimitEnabled===false?'∞':String(level.rules.moveLimit);document.querySelector('#plateObjectiveLabel')!.classList.toggle('hidden',level.objectives.requiredPlateIds.length===0);document.querySelector('#plateStatus')!.classList.toggle('hidden',level.objectives.requiredPlateIds.length===0);document.querySelector('#plateStatus')!.textContent=level.objectives.requiredPlateIds.every(id=>{const p=objects.find(o=>o.id===id);return !!p&&isPlateActive(p);})?'✓':'○';const requiredReceivers=level.objectives.requiredReceiverIds??[];document.querySelector('#receiverObjectiveLabel')!.classList.toggle('hidden',requiredReceivers.length===0);document.querySelector('#receiverStatus')!.classList.toggle('hidden',requiredReceivers.length===0);document.querySelector('#receiverStatus')!.textContent=requiredReceivers.every(id=>objects.some(o=>o.id===id&&o.type==='receiver'&&o.active))?'✓':'○';const requiredKeys=level.objectives.requiredKeyIds??[];document.querySelector('#keyObjectiveLabel')!.classList.toggle('hidden',requiredKeys.length===0);document.querySelector('#requiredKeyStatus')!.classList.toggle('hidden',requiredKeys.length===0);document.querySelector('#requiredKeyStatus')!.textContent=requiredKeys.every(id=>objects.some(o=>o.id===id&&o.type==='key'&&o.active))?'✓':'○';document.querySelector('#goalStatus')!.textContent=won?'✓':'○';document.querySelector('#moveBar')!.setAttribute('style',`width:${level.rules.moveLimitEnabled===false?0:Math.min(100,moves/Math.max(1,level.rules.moveLimit)*100)}%`);document.querySelector('#hintText')!.textContent=won?'Puzzle complete. Restart to play again or open the editor to modify this level.':`Click a block to attach. Gloves unlock walking while carrying; the belt unlocks heavy-block rotation. ${keyCount} keys · ${level.rules.moveLimitEnabled===false?'unlimited':Math.max(0,level.rules.moveLimit-moves)} walking moves remain.`;const oldKeys=document.querySelector('#keyCount');if(oldKeys)oldKeys.textContent=String(keyCount);const beltEl=document.querySelector('#beltCount');if(beltEl)beltEl.textContent=String(beltCount);const shardEl=document.querySelector('#shardCount');if(shardEl)shardEl.textContent=String(shardCount);}
function capture():Snapshot{return {level:structuredClone(level),player:structuredClone(player),objects:structuredClone(objects),attached:[...attached],moves,won,keyCount,beltCount,shardCount};}
function restore(s:Snapshot){level=structuredClone(s.level);player=structuredClone(s.player);objects=structuredClone(s.objects);attached=new Set(s.attached);moves=s.moves;won=s.won;keyCount=s.keyCount??0;beltCount=s.beltCount??0;shardCount=s.shardCount??0;if(editorMode!=='play')baseLevel=normalizeLevel(structuredClone(level));drawBoard();drawEnvironment();updateHud();syncEditor();}
function pushUndo(){undoStack.push(capture());if(undoStack.length>100)undoStack.shift();redoStack.length=0;}
function undo(){if(activeReplay)return;if(!undoStack.length){say('Nothing to undo.');return;}redoStack.push(capture());restore(undoStack.pop()!);recordRunFrame('undo');say('Action undone.');}
function redo(){if(activeReplay)return;if(!redoStack.length){say('Nothing to redo.');return;}undoStack.push(capture());restore(redoStack.pop()!);recordRunFrame('redo');say('Action redone.');}
function snapWorld(){const p=hexWorld(player);const pg=objectMeshes.get('player');if(pg)pg.position.copy(p);for(const o of objects){const g=objectMeshes.get(o.id);if(g)g.position.copy(hexWorld(o));}}
function isGateOpen(o:LevelObject){return isLinkedMechanismOpen(o,objects)||(o.requiresKey===true&&keyCount>0);}
function occupied(p:Hex,ignoreIds:string[]=[],allowVoid=false){const bridgeHere=objects.find(o=>o.type==='bridge'&&o.q===p.q&&o.r===p.r&&o.h===p.h);const declaredCell=cellAt(p);if(!hasCell(p)&&!(bridgeHere&&isLinkedMechanismOpen(bridgeHere,objects))&&!(allowVoid&&declaredCell))return true;return objects.some(o=>{if(ignoreIds.includes(o.id)||o.q!==p.q||o.r!==p.r||o.h!==p.h)return false;if(['block','wall','mirror'].includes(o.type))return true;if(o.type==='gate')return !isGateOpen(o);if(o.type==='bridge')return !isLinkedMechanismOpen(o,objects)&&o.kind!=='normallyOpen';return false;});}
