function gravity(){refreshReceiverStates(level,objects);const result=resolveGravity(level,objects,attached);objects=slideBlocksOnIce(level,result.objects,[]);for(const id of result.detachedIds){attached.delete(id);say(`${id} dropped to a lower platform and detached.`);}for(const id of result.fallenIds){attached.delete(id);say(`${id} fell into the void.`);}refreshReceiverStates(level,objects);level.objects=[structuredClone(player),...structuredClone(objects)];}
