 if(here){const d=DIRS[((here.direction??0)%6+6)%6];const next={q:player.q+d.q,r:player.r+d.r,h:player.h};const carried=objects.filter(o=>attached.has(o.id));const ignore=carried.map(o=>o.id);const translated=carried.map(o=>({...o,q:o.q+d.q,r:o.r+d.r}));if(playerCanStand(next)&&!occupied(next,ignore)&&!isPlayerHazard(next)&&translated.every(o=>!occupied(o,ignore))){player.q=next.q;player.r=next.r;for(const n of translated){const original=objects.find(o=>o.id===n.id)!;original.q=n.q;original.r=n.r;}say('Conveyor carried you one hex.');}}
