function rotateSelectedObject(){const obj=objects.find(o=>o.id===selectedObjectId);if(!obj||!['laser','mirror'].includes(obj.type)){say('Select a laser emitter or mirror in the scene first.');return;}pushUndo();obj.direction=((obj.direction??0)+1)%6;level.objects=[structuredClone(player),...structuredClone(objects)];baseLevel=normalizeLevel(structuredClone(level));drawBoard();syncEditor();say(`${obj.type} direction: ${obj.direction} (${axialName(DIRS[obj.direction])}).`);}
