function objectAtPointer():{id:string;distance:number}|null{const roots=[...objectMeshes.values()];const hits=raycaster.intersectObjects(roots,true);for(const hit of hits){let node:THREE.Object3D|null=hit.object;while(node&&!node.userData.objectId)node=node.parent;if(node?.userData.objectId)return {id:String(node.userData.objectId),distance:hit.distance};}return null;}
function describeObject(id:string){if(id==='player')return {name:'Player',detail:'Your character',connection:'No connections'};const o=objects.find(x=>x.id===id);if(!o)return null;const names:Record<string,string>={block:'Movable block',plate:'Pressure plate',goal:'Exit',wall:'Wall',lift:'Lift platform',laser:'Laser emitter',mirror:'Laser mirror',bridge:'Retractable bridge',gate:'Gate',switch:'Toggle switch',receiver:'Laser receiver',key:'Gloves pickup',belt:'Belt pickup',conveyor:'Conveyor tile',teleporter:'Paired teleporter',shard:'Resonance shard',spikes:'Spike hazard',fire:'Fire block · destroys blocks on contact'};const links:string[]=[];if(o.linkedTo){const target=objects.find(x=>x.id===o.linkedTo);links.push(`Connects to ${target?`${target.id} (${target.type})`:o.linkedTo}`);}if(o.linkedToAll?.length)links.push(`Requires all: ${o.linkedToAll.join(' + ')}`);if(o.enabledBy)links.push(`Enabled by ${o.enabledBy}`);if(o.type==='bridge')links.push(isLinkedMechanismOpen(o,objects)?'Bridge open: gap is walkable':'Bridge closed: gap is impassable');if(o.type==='conveyor')links.push(`Pushes toward ${axialName(DIRS[((o.direction??0)%6+6)%6])}`);if(o.type==='teleporter')links.push('Transfers player and attached blocks to its paired portal');if(o.type==='switch')links.push(`Switch is ${o.active?'on':'off'}`);const linkedBy=objects.filter(x=>x.linkedTo===o.id||x.linkedToAll?.includes(o.id)||x.enabledBy===o.id);for(const source of linkedBy){if(source.enabledBy===o.id)links.push(`Enables ${source.id} (${source.type})`);else if(source.linkedToAll?.includes(o.id))links.push(`Required by ${source.id} (${source.type}, AND connection)`);else links.push(`Connected from ${source.id} (${source.type})`);}if(o.type==='block'){if(o.kind==='heavy')links.push('Heavy block · activates heavy-only plates');if(o.kind==='fragile')links.push('Fragile block · breaks when it falls');links.push(attached.has(o.id)?'Attached to player · click to detach':(hexDistance(player,o)===1&&player.h===o.h?'Adjacent · click to attach':'Move adjacent to attach'));if(o.assemblyId)links.push(`Glued assembly: ${o.assemblyId}`);}if(o.type==='laser'||o.type==='mirror')links.push(`Direction: ${axialName(DIRS[((o.direction??0)%6+6)%6])}`);if(o.type==='key')links.push(o.active?'Gloves collected':'Gloves pickup · unlocks movement while carrying');if(o.type==='belt')links.push(o.active?'Belt collected':'Belt pickup · unlocks heavy-block rotation');if(o.type==='shard')links.push(o.active?'Already collected':'Collectible');if(o.type==='gate'){links.push(isGateOpen(o)?'Currently open':'Currently closed');if(o.requiresKey)links.push('Requires collected gloves');}return {name:names[o.type]||o.type,detail:`${o.id} · hex (${o.q}, ${o.r}) · height ${o.h}`,connection:links.join(' · ')||'No connections'};}
renderer.domElement.addEventListener('pointermove',(e:PointerEvent)=>{if(editorPointerDown)return;pointerNdc(e);const editorVisible=!document.querySelector('#editorPanel')!.classList.contains('hidden');const found=objectAtPointer();if(!found&&editorVisible){const hits=raycaster.intersectObjects([...world.children,...editorGrid.children],true);let hex:Hex|null=null;for(const hit of hits){let n:THREE.Object3D|null=hit.object;while(n&&!n.userData.cell&&!n.userData.editorHex)n=n.parent;if(n){hex=(n.userData.cell||n.userData.editorHex) as Hex;break;}}if(hex){tooltip.replaceChildren();const title=document.createElement('strong');title.textContent='Hex tile';const detail=document.createElement('span');detail.textContent=`q ${hex.q} · r ${hex.r} · h ${hex.h}`;const connection=document.createElement('small');connection.textContent=cellAt(hex)?'Existing tile · click with a tool to edit':'Empty grid cell · select Add tile to create';tooltip.append(title,detail,connection);tooltip.classList.remove('hidden');const stageRect=stageElement.getBoundingClientRect();tooltip.style.left=`${Math.min(stageRect.width-270,Math.max(12,e.clientX-stageRect.left+14))}px`;tooltip.style.top=`${Math.min(stageRect.height-92,Math.max(12,e.clientY-stageRect.top+14))}px`;renderer.domElement.style.cursor='crosshair';return;}}if(!found){tooltip.classList.add('hidden');drawHoverConnections(null);renderer.domElement.style.cursor='';return;}const info=describeObject(found.id);if(!info){tooltip.classList.add('hidden');return;}tooltip.replaceChildren();const title=document.createElement('strong');title.textContent=info.name;const detail=document.createElement('span');detail.textContent=info.detail;const connection=document.createElement('small');connection.textContent=info.connection;tooltip.append(title,detail,connection);tooltip.classList.remove('hidden');drawHoverConnections(found.id);const stageRect=renderer.domElement.closest('.stage')!.getBoundingClientRect();tooltip.style.left=`${Math.min(stageRect.width-270,Math.max(12,e.clientX-stageRect.left+14))}px`;tooltip.style.top=`${Math.min(stageRect.height-92,Math.max(12,e.clientY-stageRect.top+14))}px`;renderer.domElement.style.cursor=found.id!=='player'?'pointer':'';});
