renderer.domElement.addEventListener('pointerdown',(e:PointerEvent)=>{if(editorPointerDown)return;pointerNdc(e);const editorVisible=!document.querySelector('#editorPanel')!.classList.contains('hidden');if(editorVisible&&editorMode!=='play'){const cellHit=raycaster.intersectObjects([...world.children,...editorGrid.children],true).find((hit:THREE.Intersection)=>{let n:THREE.Object3D|null=hit.object;while(n&&!n.userData.cell&&!n.userData.editorHex)n=n.parent;return !!n;});if(cellHit){let n:THREE.Object3D|null=cellHit.object;while(n&&!n.userData.cell&&!n.userData.editorHex)n=n.parent;const hex=(n?.userData.cell||n?.userData.editorHex) as Hex|undefined;if(hex){editorCell=hex;applyEditorTool(hex);return;}}}const hitObject=objectAtPointer();if(hitObject){if(editorVisible){selectedObjectId=hitObject.id==='player'?null:hitObject.id;updateSelectedObjectNote();syncObjectBrowser();syncConnections();if(editorMode==='play')say(`Selected ${hitObject.id}. Choose an editing tool to modify the level.`);return;}const obj=objects.find(x=>x.id===hitObject.id);if(obj?.type==='block'){toggleAttach(obj.id);return;}return;}if(editorVisible&&editorMode!=='play'){const hits=raycaster.intersectObjects(world.children,true);for(const hit of hits){let node:THREE.Object3D|null=hit.object;while(node&&!node.userData.cell)node=node.parent;if(node?.userData.cell){editorCell=node.userData.cell as Hex;applyEditorTool(editorCell);return;}}}});
let editorPointerDown=false;renderer.domElement.addEventListener('pointerdown',(e:PointerEvent)=>{if(e.shiftKey||document.querySelector('#editorPanel')?.classList.contains('hidden'))return;pointerNdc(e);const hit=objectAtPointer();if(!hit)return;editorPointerDown=true;editorDragId=hit.id;editorDragMoved=false;selectedObjectId=hit.id==='player'?null:hit.id;pushUndo();controls.enabled=false;try{renderer.domElement.setPointerCapture(e.pointerId);}catch{}syncObjectBrowser();updateSelectedObjectNote();},{capture:true});
renderer.domElement.addEventListener('pointermove',(e:PointerEvent)=>{if(!editorPointerDown||!editorDragId)return;pointerNdc(e);const hits=raycaster.intersectObjects([...world.children,...editorGrid.children],true);let hex:Hex|null=null;for(const hit of hits){let node:THREE.Object3D|null=hit.object;while(node&&!node.userData.cell&&!node.userData.editorHex)node=node.parent;if(node){hex=(node.userData.cell||node.userData.editorHex) as Hex;break;}}if(!hex||!hasCell(hex))return;const obj=editorDragId==='player'?player:objects.find(o=>o.id===editorDragId);if(!obj||obj.q===hex.q&&obj.r===hex.r&&obj.h===hex.h)return;const solid=['block','wall','gate','bridge'].includes(obj.type);const occupant=objects.find(o=>o.id!==obj.id&&o.q===hex!.q&&o.r===hex!.r&&o.h===hex!.h&&['block','wall','gate','bridge'].includes(o.type));if(occupant&&(solid||obj.type==='player'||['key','belt','shard','goal'].includes(obj.type))){say('That hex is occupied by a solid object.');return;}obj.q=hex.q;obj.r=hex.r;obj.h=hex.h;editorDragMoved=true;level.objects=[structuredClone(player),...structuredClone(objects)];baseLevel=normalizeLevel(structuredClone(level));drawBoard();drawHoverConnections(editorDragId);});
