const movePreviewRoot=document.querySelector<HTMLDivElement>('#movePreviews')!;const movePreviewEls=new Map<string,HTMLDivElement>();for(const keyName of ['w','a','s','d']){const el=document.createElement('div');el.className='move-preview';el.innerHTML=`<kbd>${keyName.toUpperCase()}</kbd>`;movePreviewRoot.append(el);movePreviewEls.set(keyName,el);}function updateMovePreviews(){const stageRect=stageElement.getBoundingClientRect();for(const keyName of ['w','a','s','d']){const el=movePreviewEls.get(keyName)!;const dir=screenDirection(keyName);const target={q:player.q+dir.q,r:player.r+dir.r,h:player.h};const cell=cellAt(target);const bridge=objects.find(o=>o.type==='bridge'&&o.q===target.q&&o.r===target.r&&o.h===target.h&&isLinkedMechanismOpen(o,objects));if((!cell&&!bridge)||cell?.kind==='void'||cell?.support===false){el.classList.add('unavailable');el.style.display='none';continue;}const worldPos=hexWorld(target).add(new THREE.Vector3(0,.38,0));worldPos.project(camera);if(worldPos.z>1||worldPos.z< -1){el.style.display='none';continue;}const rect=renderer.domElement.getBoundingClientRect();el.style.left=`${rect.left-stageRect.left+(worldPos.x*.5+.5)*rect.width}px`;el.style.top=`${rect.top-stageRect.top+(-worldPos.y*.5+.5)*rect.height}px`;el.style.display='flex';el.classList.toggle('unavailable',occupied(target)||isPlayerHazard(target));}}
